import { prisma } from '../../../lib/prisma';
import CaddyCard from '../../../components/CaddyCard';
import Link from 'next/link';

export default async function CaddyDetailPage({ params }: { params: { id: string } }) {
  try {
    // Fetch the caddy profile with user and reviews
    const caddy = await prisma.caddyProfile.findUniqueOrThrow({
      where: { id: params.id },
      include: {
        user: true, // Need this for the name
        reviewsReceived: { // Need this for the review list
          orderBy: { createdAt: 'desc' },
          include: { author: true } // Need this for the reviewer's name
        }
      }
    });

    // Increment the profile view counter
    await prisma.caddyProfile.update({
      where: { id: params.id },
      data: { profileViews: { increment: 1 } }
    });

    return (
      <main className="p-4 md:p-8 bg-gray-50 min-h-screen">
        {/* Back Button */}
        <Link 
          href="/caddies" 
          className="inline-block mb-6 px-4 py-2 bg-white border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors"
        >
          ← Back to All Caddies
        </Link>

        {/* Detailed Card */}
        <div className="max-w-2xl mx-auto my-6">
          <CaddyCard caddy={caddy} />
        </div>

        {/* Reviews Section */}
        <div className="max-w-2xl mx-auto mt-8">
          <h2 className="text-2xl font-bold mb-4">รีวิว ({caddy.reviewsReceived.length})</h2>
          <div className="space-y-4">
            {caddy.reviewsReceived.map((review: any) => (
              <div key={review.id} className="p-4 bg-white shadow rounded-lg">
                <p className="font-semibold">{review.author.name}</p>
                <p className="text-sm text-gray-500">{review.createdAt.toLocaleDateString()}</p>
                <div className="flex items-center gap-2 mt-1">
                  <div className="flex gap-1">
                    {/* Star Rating Display */}
                    {Array.from({ length: 5 }).map((_, index) => (
                      <span key={index} className={index < review.rating ? 'text-yellow-500' : 'text-gray-300'}>
                        ★
                      </span>
                    ))}
                  </div>
                  <span className="text-sm text-gray-600">({review.rating}/5)</span>
                </div>
                {review.comment && <p className="mt-2">{review.comment}</p>}
              </div>
            ))}
            {caddy.reviewsReceived.length === 0 && (
              <p className="text-gray-500 text-center py-8">ยังไม่มีรีวิว...</p>
            )}
          </div>
        </div>
      </main>
    );
  } catch (error) {
    return (
      <main className="p-4 md:p-8 bg-gray-50 min-h-screen">
        <div className="max-w-2xl mx-auto text-center py-16">
          <h1 className="text-3xl font-bold text-gray-900 mb-4">Caddy not found</h1>
          <p className="text-gray-600 mb-6">The caddy you're looking for doesn't exist.</p>
          <Link 
            href="/caddies" 
            className="inline-block px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            Back to All Caddies
          </Link>
        </div>
      </main>
    );
  }
}
